# The events plot's data: quality checks and work orders (custom.events, every 10 minutes), scrap (custom.scrap, every minute)
# and SPC alerts (custom.spcAlerts' markers, every 10 minutes; a hover listing the measures and rules)
from cgi import escape
from bisect import bisect_right
# Times in the device's time zone, as the plot shows them
from java.text import SimpleDateFormat
from java.util import TimeZone
def dfmt(d, pattern):
	f = SimpleDateFormat(pattern)
	if value['tz']: f.setTimeZone(TimeZone.getTimeZone(value['tz']))
	return f.format(d)
out = dict(value['events'] or {})
scrap = list(value['scrap'] or [])
out['scrap'] = scrap
out['spc'] = [{'x': m['x'], 'kind': m['kind'], 'tip': '<b>SPC alerts</b><br>' + '<br>'.join([escape(l) for l in (m['tip'] or '').split('\n')])}
	for m in (value['spc'] or {}).get('markers') or []]
# Uncoded scrap, from the counts already read for the lines (custom.lineData, by hour; by day or week past 35 days): a
# bucket's waste less its coded waste (custom.scrap). Marked at the bucket's start when it is at least uncodedScrapPercent
# (5 by default) of the bucket's infeed; waste in other units than infeed is compared with outfeed when their units match,
# else any uncoded waste is marked
lines, metrics = value['lines'] or {}, value['metrics'] or {}
try: pct = float(value['pct'])
except (TypeError, ValueError): pct = 5.0
hours = lines.get('hours') or 1
# (a bucket where more than one item ran comes as a row per item: summed into one)
buckets = {}
for r in lines.get('rows') or []:
	if not r or r[0] is None: continue
	b = buckets.setdefault(r[0], [r[0], 0, 0, 0])
	for k in (1, 2, 3): b[k] += r[k] or 0
rows = [buckets[k] for k in sorted(buckets)]
starts = [r[0] for r in rows]
step = (lambda d: system.date.addHours(d, 1)) if hours == 1 else (lambda d: system.date.addDays(d, 1)) if hours == 24 else (lambda d: system.date.addDays(d, 7))
ends = [system.date.toMillis(step(system.date.fromMillis(s))) for s in starts]
coded = [0.0] * len(rows)
for s in scrap:
	i = bisect_right(starts, s['x']) - 1
	if i >= 0 and s['x'] < ends[i]: coded[i] += s['qty'] or 0
wasteUnits, infeedUnits, outfeedUnits = [metrics.get(k) or '' for k in ('wasteUnits', 'infeedUnits', 'outfeedUnits')]
if wasteUnits != 'mixed' and wasteUnits == infeedUnits: base, baseName = 1, 'infeed'
elif wasteUnits != 'mixed' and wasteUnits == outfeedUnits: base, baseName = 2, 'outfeed'
else: base, baseName = None, None
units = '' if wasteUnits == 'mixed' else wasteUnits
qty = lambda q: '{:,g}'.format(round(q, 1)) + ((' ' + escape(units)) if units else '')
bucket = {1: 'hour', 24: 'day'}.get(hours, 'week')
def span(a, b):
	if hours == 1: return '%s to %s' % (dfmt(a, 'MMM d, HH:mm'), dfmt(b, 'HH:mm'))
	if hours == 24: return dfmt(a, 'MMM d')
	return '%s to %s' % (dfmt(a, 'MMM d'), dfmt(system.date.addDays(b, -1), 'MMM d'))
uncoded, total = [], 0.0
for i, r in enumerate(rows):
	waste = (r[3] or 0) - coded[i]
	if waste < 1e-6: continue
	total += waste
	feed = (r[base] or 0) if base else 0
	if base is None: share, note = None, 'waste is in %s, infeed in %s and outfeed in %s: every %s with uncoded waste is marked' % (
		escape(wasteUnits or 'no units'), escape(infeedUnits or 'no units'), escape(outfeedUnits or 'no units'), bucket)
	elif feed <= 0: share, note = None, 'no %s counted in the %s' % (baseName, bucket)
	else: share, note = 100.0 * waste / feed, None
	if share is not None and share < pct - 1e-9: continue
	tip = '<b>Uncoded waste</b><br>%s%s<br>%s%s' % (qty(waste),
		(', %s%% of %s (marked from %s%%)' % ('{:,g}'.format(round(share, 1)), baseName, '{:g}'.format(pct))) if share is not None else '',
		span(system.date.fromMillis(r[0]), system.date.fromMillis(ends[i])), ('<br>' + note) if note else '')
	uncoded.append({'x': r[0], 'qty': waste, 'share': share, 'tip': tip})
# Marks close enough to overlap (within 1% of the range, about a mark's width) are one mark: the coded scrap's hover lists each reason with its
# quantity and the total, the uncoded scrap's each bucket (out['scrap'] keeps every count, for the Scrap Reasons list)
values = value['values'] or {}
try: tol = 0.01 * (system.date.toMillis(values['endDate']) - system.date.toMillis(values['startDate']))
except: tol = 0
def merge(marks):
	groups = []
	for m in marks:
		if groups and m['x'] - groups[-1][0]['x'] <= tol: groups[-1].append(m)
		else: groups.append([m])
	return groups
fmt = lambda x: dfmt(system.date.fromMillis(x), 'MMM d, HH:mm')
marks = []
for grp in merge(scrap):
	if len(grp) == 1:
		marks.append({'x': grp[0]['x'], 'tip': grp[0]['tip']})
		continue
	totals, categories = {}, {}
	for s in grp:
		totals[s['reason']] = totals.get(s['reason'], 0) + (s['qty'] or 0)
		categories[s['reason']] = s['category']
	when = fmt(grp[0]['x']) if grp[-1]['x'] == grp[0]['x'] else '%s to %s' % (fmt(grp[0]['x']), dfmt(system.date.fromMillis(grp[-1]['x']), 'HH:mm'))
	marks.append({'x': grp[0]['x'], 'tip': '<b>%d scrap reason%s, %s</b><br>%s<br>%s' % (len(totals), '' if len(totals) == 1 else 's', qty(sum(totals.values())),
		'<br>'.join(['%s%s: %s' % (escape(n or ''), (' &middot; %s' % escape(categories[n])) if categories.get(n) else '', qty(totals[n]))
			for n in sorted(totals, key=lambda n: -totals[n])]), when)})
