unmarks = [grp[0] if len(grp) == 1 else {'x': grp[0]['x'], 'qty': sum([m['qty'] for m in grp]),
	'tip': '<b>Uncoded waste in %d %ss, %s</b><br>' % (len(grp), bucket, qty(sum([m['qty'] for m in grp]))) + '<br>'.join([m['tip'].replace('<b>Uncoded waste</b><br>', '') for m in grp])}
	for grp in merge(uncoded)]
# A coded and an uncoded mark that touch on the plot (within 1% of the range) each show the other's hover too, as either
# can be the one under the pointer
sep = '<div style="margin:4px 0;border-top:1px solid rgba(128,128,128,0.4)"></div>'
codedTips, uncodedTips = [m['tip'] for m in marks], [u['tip'] for u in unmarks]
for i, m in enumerate(marks):
	for j, u in enumerate(unmarks):
		if abs(m['x'] - u['x']) <= tol:
			m['tip'] += sep + uncodedTips[j]
			u['tip'] += sep + codedTips[i]
out['scrapUncoded'] = unmarks
# Checks and work orders close enough to overlap (within 1% of the range) are one mark too, showing the most serious status
# among them, so a long range doesn't draw thousands of marks; its hover lists each one's (out['events'] keeps them all)
rank = {'failed': 5, 'missed': 4, 'overdue': 3, 'inprogress': 2, 'upcoming': 1, 'passed': 0, 'done': 0}
def mergeMarks(marks, what):
	res = []
	for grp in merge(sorted(marks or [], key=lambda m: m['x'])):
		if len(grp) == 1:
			res.append(grp[0])
			continue
		worst = max(grp, key=lambda m: rank.get(m.get('status'), 0))
		tips = [m['tip'] for m in grp[:8]] + (['and %d more' % (len(grp) - 8)] if len(grp) > 8 else [])
		res.append(dict(worst, x=grp[0]['x'], tip=('<b>%d %s</b><br>' % (len(grp), what)) + sep.join(tips)))
	return res
if 'checks' in out: out['checks'] = mergeMarks(out['checks'], 'quality checks')
if 'workOrders' in out: out['workOrders'] = mergeMarks(out['workOrders'], 'work orders')
