start, end, assetId = values.get('startDate'), values.get('endDate'), values.get('assetId')
if start is None or end is None or assetId is None: return {'hours': 1, 'rows': [], 'key': ''}
days = system.date.daysBetween(start, end)
hours, interval = (1, 'Hour') if days <= 35 else (24, 'Day') if days <= 200 else (168, 'Week')
key = '%s|%s|%s|%s' % (assetId, system.date.toMillis(start), system.date.toMillis(end), hours)
slow = value['slow']
def read(a, b):
