		for r in (system.dataset.toPyDataSet(data) if data is not None and not isinstance(data, basestring) else [])]
prev = self.custom.lineData or {}
now = system.date.now()
# Only up to now: the procedure returns a row for every bucket to the range's end, future ones too, and they cost as much
upTo = now if system.date.isBefore(now, end) else end
# (the tick arriving after the first read as the view opens isn't a new 10-minute cycle: a read with no tick counts as one)
if hours in (1, 24) and prev.get('key') == key and prev.get('slow') in (slow, None) and prev.get('rows') is not None and system.date.isAfter(now, start):
	# The bucket before the current one, on its boundary: an hour or a day
	if hours == 1: since = system.date.addHours(system.date.setTime(now, system.date.getHour24(now), 0, 0), -1)
	else: since = system.date.addDays(system.date.midnight(now), -1)
	if system.date.isBefore(since, start): since = start
	cut = system.date.toMillis(since)
	rows = [list(r) for r in prev['rows'] if r[0] < cut] + read(since, upTo)
	return {'hours': hours, 'rows': rows, 'key': key, 'slow': slow}
return {'hours': hours, 'rows': read(start, upTo) if system.date.isAfter(upTo, start) else [], 'key': key, 'slow': slow}

	# Re-read every minute while the range reaches now (custom.refreshTick); the progress bar shows for a new range only
	value = value['values'] or {}
