# SPC alerts from the asset's measures over the chart's range: each measure with SPC on (its tag's spcCheckEnabled) has its
# values in the range checked as the Measure SPC widget and the tag's update script check them (individuals, Western
# Electric and Nelson rules, the tag's limits). Nothing stores past alerts, so they're worked out here, with today's limits.
# The points that break a rule are grouped by chart interval: one marker each, coloured by the most serious kind
values = value['values'] or {}
start, end, assetId, interval = values.get('startDate'), values.get('endDate'), values.get('assetId'), values.get('interval')
empty = {'markers': [], 'measures': []}
if assetId is None or start is None or end is None: return empty
tagPath = system.kanoa.utilities.getFieldValue('tagPath', system.kanoa.asset.getAssets({'assetId': assetId}))
measures = system.kanoa.measures.getMeasures({'assetId': assetId, 'enabled': True})
if not tagPath or measures is None or measures.rowCount == 0: return empty
# The chart's interval, as mes.spGetOEEDataByInterval picks it
if interval in ('Hour', 'Day', 'Week'): hours = {'Hour': 1, 'Day': 24, 'Week': 168}[interval]
elif system.date.hoursBetween(start, end) <= 48: hours = 1
elif system.date.daysBetween(start, end) <= 20: hours = 24
else: hours = 168
t0, step = system.date.toMillis(start), hours * 3600000
ruleInfo = system.kanoa.quality.spc.getRuleInfo()
if not isinstance(ruleInfo, dict): ruleInfo = {}
rank = {'limit': 3, 'pattern': 2, 'variation': 1}
buckets, summary = {}, []
for m in system.dataset.toPyDataSet(measures):
	base = '%s/measures/%s' % (tagPath, m['measureName'])
	names = ['spcCheckEnabled', 'spec/lsl', 'spec/lcl', 'spec/tgt', 'spec/ucl', 'spec/usl']
	reads = system.tag.readBlocking([base + '/' + n for n in names])
	if not reads[0].quality.isGood() or not reads[0].value: continue
	lsl, lcl, tgt, ucl, usl = [r.value for r in reads[1:]]
	events = system.kanoa.measures.getMeasureEvents({'measureId': m['measureId'], 'tStampStart': start, 'tStampEnd': end, 'maxRows': 0})
	points = []
	if events is not None:
		for e in system.dataset.toPyDataSet(events):
			if e['measureValue'] is not None: points.append((system.date.toMillis(e['tStamp']), e['measureValue']))
	counts = {'limit': 0, 'pattern': 0, 'variation': 0}
	if len(points) >= 2:
		info = system.kanoa.quality.spc.spcCheck([p[1] for p in points], 'individuals', 'both', None, usl, lsl, None, ucl, lcl, tgt)
		if isinstance(info, dict):
			# An alert is a stretch of consecutive points in violation, whatever rules it breaks (a rule over a sliding window,
			# such as 4 of 5 beyond 1 sigma, flags every window of a drift), of the most serious kind in it
			worst = {}
			for rule, indexes in (info.get('violationPoints') or {}).items():
				kind = (ruleInfo.get(rule) or {}).get('kind') or 'pattern'
				for i in indexes:
					if rank.get(kind, 0) > rank.get(worst.get(i), 0): worst[i] = kind
			run = None
			for i in sorted(worst):
				if run is not None and i == run[1] + 1:
					run = (run[0], i, worst[i] if rank[worst[i]] > rank[run[2]] else run[2])
				else:
					if run is not None: counts[run[2]] += 1
					run = (i, i, worst[i])
			if run is not None: counts[run[2]] += 1
			for rule, indexes in (info.get('violationPoints') or {}).items():
				kind = (ruleInfo.get(rule) or {}).get('kind') or 'pattern'
				label = (ruleInfo.get(rule) or {}).get('label') or rule
				for i in indexes:
					b = buckets.setdefault((points[i][0] - t0) // step, {'kind': None, 'lines': {}})
					if rank.get(kind, 0) > rank.get(b['kind'], 0): b['kind'] = kind
					key = (m['measureName'], label)
					b['lines'][key] = b['lines'].get(key, 0) + 1
	summary.append({'name': m['measureName'], 'tagPath': base, 'limit': counts['limit'], 'pattern': counts['pattern'], 'variation': counts['variation'], 'points': len(points)})
markers = []
for n in sorted(buckets):
	b = buckets[n]
	lines = ['%s: %s (%d point%s)' % (name, label, c, '' if c == 1 else 's') for (name, label), c in sorted(b['lines'].items())]
	markers.append({'x': t0 + n * step + step // 2, 'kind': b['kind'], 'tip': '\n'.join(lines)})
return {'markers': markers, 'measures': summary}

