		elif key == 'scrapMarks': discrete.append({'seriesIndex': s, 'dataPointIndex': i, 'fillColor': '#ba1a1a', 'strokeColor': '#ba1a1a', 'size': 6})
		elif key == 'scrapUncoded': discrete.append({'seriesIndex': s, 'dataPointIndex': i, 'fillColor': '#e8a200', 'strokeColor': '#e8a200', 'size': 6})
		else:
