			discrete.append({'seriesIndex': s, 'dataPointIndex': i, 'fillColor': colors.get(e['status'], '#777777'),
				'strokeColor': '#777777' if upcoming else '#ffffff', 'size': 7})
return {'size': 7, 'shape': [r[2] for r in rows], 'strokeWidth': [2 if r[0] == 'scrapUncoded' else 1.5 for r in rows],
	'fillOpacity': [0 if r[0] == 'scrapUncoded' else 1 for r in rows], 'discrete': discrete, 'hover': {'sizeOffset': 2}}

