# A section for each run (custom.runCounts): its work order and item, its time in Production and its dates, its counts and
# rates. A run with no work order shows its item alone; a series hidden in the display options isn't listed. Each count's
# bar is its line's colour. The counts and rates show while the pointer is over the section (kanoaRunDetails, in the
# stylesheet). A run opens the Count Editor for its start and end when the user can edit operations
from cgi import escape
locale = self.session.props.locale
def tr(s):
	return system.util.translate(s, locale)
opts = value['opts'] or {}
def show(k):
	try: return bool(opts[k])
	except: return True
short = {'second': 'sec', 'minute': 'min', 'hour': 'hr', 'day': 'day', 'week': 'wk'}
secsPer = {'second': 1, 'minute': 60, 'hour': 3600, 'day': 86400, 'week': 604800}
def num(n):
	return '{:,}'.format(int(round(n))) if abs(n) >= 100 else '{:,g}'.format(round(n, 2))
def text(secs):
	return system.kanoa.utilities.secondsToText(int(secs), {'showSecs': False, 'showDays': False}) or ''
row = ('<div style="display:flex;gap:8px;justify-content:space-between;align-items:baseline;border-left:3px solid %s;padding-left:6px">'
	'<span style="color:var(--kcOnSurfaceVariant);text-transform:uppercase;font-size:0.85em;letter-spacing:0.04em">%s</span>'
	'<span style="font-weight:600;white-space:nowrap">%s</span></div>')
from java.text import SimpleDateFormat
from java.util import TimeZone, Locale
def dfmt(d, pattern):
	# Month names in the session's language
	f = SimpleDateFormat(pattern, Locale.forLanguageTag(str(self.session.props.locale or 'en-US').replace('_', '-')))
	if value['tz']: f.setTimeZone(TimeZone.getTimeZone(value['tz']))
	return f.format(d)
def dates(a, b):
	if a is None: return ''
	if b is None: return dfmt(a, 'MMM d, HH:mm')
	return '%s - %s' % (dfmt(a, 'MMM d, HH:mm'), dfmt(b, 'HH:mm' if dfmt(a, 'yyyyMMdd') == dfmt(b, 'yyyyMMdd') else 'MMM d, HH:mm'))
links = value['links'] or {}
try: link = bool(links['canEditOperations'])
except: link = False
try: assetId = links['assetId']
except: assetId = None
instances = []
for g in value['rows'] or []:
	name = '%s - %s' % (g['workOrder'], g['item']) if g['workOrder'] else g['item']
	parts = ['<div style="display:flex;justify-content:space-between;gap:8px;align-items:baseline">'
		'<span style="font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="%s">%s</span>'
		'<span style="white-space:nowrap;color:var(--kcOnSurfaceVariant)">%s</span></div>' % (escape(name, True), escape(name), escape(text(g['durationSecs'])))]
	for key, label, color, units, opt in [('targetCount', 'Target', 'var(--kcOnSurfaceVariant)', g['infeedUnits'], 'showTarget'),
			('infeedCount', 'Infeed', 'var(--kcPrimary)', g['infeedUnits'], 'showInfeed'), ('outfeedCount', 'Outfeed', 'var(--kcTertiary)', g['outfeedUnits'], 'showOutfeed'),
			('wasteCount', 'Waste', 'var(--kcError)', g['wasteUnits'], 'showWaste')]:
		if show(opt) and g[key]: parts.append(row % (color, escape(tr(label)), escape(('%s %s' % (num(g[key]), units or '')).strip())))
	period = (g['period'] or 'hour').lower()
	per = '%s/%s' % (g['infeedUnits'] or tr('units'), short.get(period, period))
	rates = sorted(g['rates'] or [])
	if rates:
		rate = num(rates[0]) if len(rates) == 1 else '%s-%s' % (num(rates[0]), num(rates[-1]))
		parts.append(row % ('transparent', escape(tr('Target Rate')), escape('%s %s' % (rate, per))))
	# The run's infeed over its run time
	if g.get('rateSecs'):
		parts.append(row % ('transparent', escape(tr('Actual Rate')), escape('%s %s' % (num(g['rateTimesSecs'] / g['rateSecs'] * secsPer.get(period, 3600)), per))))
	head = parts[0] + '<div style="color:var(--kcOnSurfaceVariant)">%s</div>' % escape(dates(g['startDate'], g['endDate']))
	details = '<div class="kanoaRunDetails" style="flex-direction:column;gap:3px">%s</div>' % ''.join(parts[1:]) if len(parts) > 1 else ''
	instances.append({'value': {'html': '<div style="display:flex;flex-direction:column;gap:3px">%s%s</div>' % (head, details),
		'assetId': assetId, 'startDate': g['startDate'], 'endDate': g['endDate'], 'link': link}})
return instances

